botster.register{
  handlers = {{ kind = "mcp_tool", id = "h_t", name = "t", description = "d", input_schema = { type = "object" },
    call = function(payload, request)

      local published, readable = {}, {}
      for _, n in ipairs(payload.published) do published[n] = true end
      for _, n in ipairs(payload.readable) do readable[n] = true end
      local unpublished_readable, published_unreadable, lookup_missing = 0, 0, 0
      for n in pairs(readable) do if not published[n] then unpublished_readable = unpublished_readable + 1 end end
      for n in pairs(published) do
        if not readable[n] then published_unreadable = published_unreadable + 1 end
        -- the real lookup of each published name, through whatever the environment does for it
        if _ENV[n] == nil then lookup_missing = lookup_missing + 1 end
      end
      return { unpublished_readable = unpublished_readable, published_unreadable = published_unreadable, lookup_missing = lookup_missing }
    end }},
}
